import { useColorMode } from "@kobalte/core";
import type { Component, ComponentProps } from "solid-js";

import { Toaster as Sonner } from "solid-sonner";
import IconCheckCircle from "~icons/ph/check-circle";
import IconCircleNotch from "~icons/ph/circle-notch";
import IconInfo from "~icons/ph/info";
import IconWarning from "~icons/ph/warning";
import IconWarningOctagon from "~icons/ph/warning-octagon";

type ToasterProps = ComponentProps<typeof Sonner>;

const Toaster: Component<ToasterProps> = (props) => {
  const { colorMode } = useColorMode();

  return (
    <Sonner
      theme={colorMode()}
      class="group toaster"
      icons={{
        success: <IconCheckCircle class="size-4" />,
        info: <IconInfo class="size-4" />,
        warning: <IconWarning class="size-4" />,
        error: <IconWarningOctagon class="size-4" />,
        loading: <IconCircleNotch class="size-4 animate-spin" />,
      }}
      style={{
        "--normal-bg": "var(--popover)",
        "--normal-text": "var(--popover-foreground)",
        "--normal-border": "var(--border)",
        "--border-radius": "var(--radius)",
      }}
      toastOptions={{
        classes: {
          toast: "cn-toast",
        },
      }}
      {...props}
    />
  );
};

export { Toaster };
